	'workshop_safety_h1' => 'Workshop & Safety',
	'workshop_safety_intro' => 'The workshop is at 27 Slipway Road, Port Aldren. Students meet PPE, fume extraction and the booth rules before they work alone.',
	'workshop_safety_next' => 'Admissions',
	'workshop_safety_p1_alt' => 'Gloved hands filing a steel block square in a bench vice',
